import json


def export(value, ctx, **options):
    blob = ctx.write_blob(
        "summary.json",
        json.dumps(value, allow_nan=False, indent=2).encode(),
        media_type="application/json",
    )
    return {
        "format": "summary.json.v1",
        "media_type": "application/json",
        "data": {
            "type": "bundle",
            "files": {"data": blob},
            "entry": "data",
        },
        "metadata": {"kind": "finance-summary"},
    }

